using System;
using System.Drawing;
using System.Windows.Forms;
namespace AminPhoneBook {
 public class SettingsForm:Form {
  public SettingsForm(AppSettings s){var theme=ThemeColors.Get(s);Text="تنظیمات ظاهر و برنامه";Width=520;Height=390;StartPosition=FormStartPosition.CenterParent;RightToLeft=RightToLeft.Yes;RightToLeftLayout=true;Ui.StyleForm(this,theme);var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=7,Padding=new Padding(24)};p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,58));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,42));
   var dark=new CheckBox{Text="حالت تاریک",Checked=s.DarkMode,AutoSize=true,ForeColor=theme.Text,Font=new Font("Tahoma",10,FontStyle.Bold)};var auto=new CheckBox{Text="پشتیبان‌گیری خودکار",Checked=s.AutoBackup,AutoSize=true,ForeColor=theme.Text};var days=new NumericUpDown{Minimum=1,Maximum=90,Value=s.AutoBackupDays,Width=120};var conf=new CheckBox{Text="تأیید قبل از حذف",Checked=s.ConfirmDelete,AutoSize=true,ForeColor=theme.Text};var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=180,Font=new Font("Tahoma",9)};combo.Items.AddRange(new object[]{"Ocean","Purple","Emerald","Sunset"});combo.SelectedItem=s.Theme??"Ocean";p.Controls.Add(new Label{Text="پوسته رنگی",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight,ForeColor=theme.Muted},0,0);p.Controls.Add(combo,1,0);p.Controls.Add(dark,0,1);p.SetColumnSpan(dark,2);p.Controls.Add(auto,0,2);p.SetColumnSpan(auto,2);p.Controls.Add(new Label{Text="دوره پشتیبان‌گیری (روز)",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight,ForeColor=theme.Muted},0,3);p.Controls.Add(days,1,3);p.Controls.Add(conf,0,4);p.SetColumnSpan(conf,2);var save=Ui.Button("✓  ذخیره تنظیمات",theme,true);p.Controls.Add(save,0,6);p.SetColumnSpan(save,2);Controls.Add(p);save.Click+=(x,e)=>{s.DarkMode=dark.Checked;s.AutoBackup=auto.Checked;s.AutoBackupDays=(int)days.Value;s.ConfirmDelete=conf.Checked;s.Theme=combo.SelectedItem==null?"Ocean":combo.SelectedItem.ToString();DialogResult=DialogResult.OK;Close();};Shown+=(s1,e)=>Ui.FadeIn(this);}
 }
}